True def transform(grid):
    """Fill background cells between the outermost markers in each row/column."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    bg = 8
    fill = 2
    # Horizontal spans
    for r in range(h):
        cols = [c for c, value in enumerate(grid[r]) if value != bg]
        if len(cols) >= 3:
            for c in range(min(cols) + 1, max(cols)):
                if grid[r][c] == bg:
                    out[r][c] = fill
    # Vertical spans
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] != bg]
        if len(rows) >= 3:
            for r in range(min(rows) + 1, max(rows)):
                if grid[r][c] == bg:
                    out[r][c] = fill
    return out
